        '旅の幕開けとなるタランギレには、正味半日の時間がしっかりと確保されているほか、ムト・ワ・ンブへの立ち寄りとマサイ族コミュニティ訪問も、単なる付け足しではなくルート本来の一部として組み込まれています——東アフリカ屈指のゾウの個体数を誇り、乾季には川沿いに群れが集中する地域です。ンゴロンゴロ・クレーターは、慌ただしい午前の立ち寄りではなく丸1日をかけて巡ります。面積約260平方キロメートルの陥没した火山カルデラで、その急峻な壁のおかげで内部に暮らす動物のほとんどは一生外へ出ることがなく、この旅程の中でも最も濃密な野生動物観察の一日となります。続くセレンゲティでは、定住型の捕食動物が生息するエリアで丸2日間を過ごし、その後アルーシャ経由の遊覧フライトで車両から解き放たれ、ヌングウィの白砂の上で3泊、予定を何も入れない時間へと切り替わります。',
