        '10日間にわたるこのフォトグラフィックサファリは、タンザニア北部の中でも特に実りの多い4つのエリアを巡ります。まずはタランギーレのゾウの群れと古代のバオバブから始まり、野生動物の密度が高いンゴロンゴロ・クレーターの底で終日を過ごし、その後セレンゲティへ——まずはアフリカ大陸でも屈指の確実さで大型ネコ科動物に出会える中央の平原、そして光が黄金色に染まり、地平線がどこまでも続く北部の大移動エリアへと向かいます。どの一日も、公園をただチェックリストのように消化するのではなく、光、位置取り、そして忍耐を中心に組み立てられています。',
