          '車両は単に動物との距離だけでなく、光の角度も考慮して位置取りされます。太陽の光が最良の角度で当たるならば、あえて意外な方向から近づくこともあります。ある光景での滞在時間は、決まったスケジュールのペースではなく、写真に必要な忍耐によって決まります——プライドが動き出しそうであれば、じっと待ちます。そしてガイドの役割は動物を見つけるだけではありません。20分後にどこに光が差すか、背景がいつ邪魔なブッシュから開けるか、次の無線連絡を追いかけるよりもその場に留まる価値があるのはいつか、といったことを読み取っています。',
